    const failSafeA = Number(flow.get('dynamic_load_balancing_failsafe_amp') || 6);
    const fallbackV = Number(flow.get('dynamic_load_balancing_voltage_fallback') || 215);
    const rawV = [Number(flow.get('p1_phase_1_voltage')), Number(flow.get('p1_phase_2_voltage')), Number(flow.get('p1_phase_3_voltage'))];
    const voltages = rawV.map(v => Number.isFinite(v) && v >= 180 && v <= 260 ? v : fallbackV);
    const activePhases = [...new Set(active.map(i => phaseOf[i]))];
