    if (voltageFallback.length) reasons.push('Voltage fallback ' + fallbackV + 'V on ' + voltageFallback.join('/'));
    if (hardProtectionActive) reasons.push('Hard phase protection at ' + maxA.toFixed(1) + 'A');
    if (softRampDownActive) reasons.push('Soft ramp-down step limited above ' + softA.toFixed(1) + 'A; step ' + softRampDownStepW + 'W');
    else if (softProtectionActive) reasons.push('Soft phase protection above ' + softA.toFixed(1) + 'A');
    if (result.redistributed > 0.5) reasons.push('Redistributed ' + Math.floor(result.redistributed) + 'W across phase groups');
    if (result.rampDelayed) reasons.push('Ramp-up waiting for consecutive phase headroom');
    else if (result.rampActive) reasons.push('Ramp-up limited by ' + Math.floor(result.rampLimitedW || 0) + 'W');
    if (result.remaining > 1 && !result.rampActive && !result.rampDelayed) reasons.push('No safe capacity for ' + Math.floor(result.remaining) + 'W');

    flow.set('dlb_input_total_requested', requested);
    flow.set('dlb_input_charge_eligible', eligible);
    flow.set('dlb_input_charge_weights', weights);
    flow.set('dlb_last_normal_allocation_timestamp', now);
    ['A','B','C'].forEach((k,i)=>{ flow.set('dlb_input_requested_'+k,wanted[i]); flow.set('dlb_input_applied_'+k,result.target[i]); });
    [1,2,3].forEach((p,i)=>{ flow.set('dlb_phase_'+p+'_capacity_W', phaseBudget[i]); flow.set('dlb_phase_'+p+'_used_W', result.phaseUsed[i]); });
    flow.set('dlb_phase_mapping_text', active.map(i=>'Z'+(i+1)+'→'+phaseNames[i]).join(', '));
    flow.set('dlb_phase_mapping_standard', standardMapping ? 1 : 0);
    flow.set('dlb_limited', limited ? 1 : 0);
    flow.set('dlb_throttling', limited ? 1 : 0);
    flow.set('dlb_redistributing', result.redistributed > 0.5 ? 1 : 0);
    flow.set('dlb_redistributed_W', Math.floor(result.redistributed));
