        }
    }
    return { A:result.target[0], B:result.target[1], C:result.target[2], limited:limited?1:0, throttling:limited?1:0, redistributionActive:result.redistributed>0.5?1:0, redistributedW:Math.floor(result.redistributed), rampActive:(result.rampActive||result.rampDelayed)?1:0, rampLimitedW:Math.floor(result.rampLimitedW||0), phaseCaps:phaseBudget, phaseVoltages:voltages, previous };
