        // remove zero-power devices when soc limit reached and then check which are to be displayed as active
        let devices_active_nonzero_power = devices_active;
        if ((devices_active_nonzero_power.some(d => d.name === "device_A")) && Power_A === 0 && socLimit_A == 1) {    // if device is active and power is zero and limit reached
            devices_active_nonzero_power = devices_active_nonzero_power.filter(     // remove device
                d => d.name !== "device_A"
            );
        }
        if ((devices_active_nonzero_power.some(d => d.name === "device_B")) && Power_B === 0 && socLimit_B == 1) {    // if device is active and power is zero and limit reached
            devices_active_nonzero_power = devices_active_nonzero_power.filter(     // remove device
                d => d.name !== "device_B"
            );
        }
        if ((devices_active_nonzero_power.some(d => d.name === "device_C")) && Power_C === 0 && socLimit_C == 1) {    // if device is active and power is zero and limit reached
