        let singleMode_activedevice = devices_active_nonzero_power.reduce((mask, d) => {
            return mask | (deviceMap[d.name] || 0);
        }, 0);

        flow.set('singleMode_activedevice', singleMode_activedevice);
        if (debug) node.warn("singleMode_activedevice is " + singleMode_activedevice);

    }


