    // phase capacities, then reallocates blocked charging power to other
    // Zendures that still have room. Discharge behaviour is unchanged.
    const dlbChargeEligible = [
        electricLevel_A < (socSet / 10) && socStatus_A !== 1 && socLimit_A !== 1,
        electricLevel_B < (socSet / 10) && socStatus_B !== 1 && socLimit_B !== 1,
        electricLevel_C < (socSet / 10) && socStatus_C !== 1 && socLimit_C !== 1
