        Math.pow(Math.max(0, (socSet / 10) - electricLevel_A), balancingFactor),
        Math.pow(Math.max(0, (socSet / 10) - electricLevel_B), balancingFactor),
        Math.pow(Math.max(0, (socSet / 10) - electricLevel_C), balancingFactor)
