        'latestPowerCmd_1_zero_timestamp',
        'latestPowerCmd_2_zero_timestamp',
        'latestPowerCmd_3_zero_timestamp'
    ];
    for (let i = 0; i < device_count; i++) {
        if (dlbActualPowers[i] > 0) {
            flow.set(dlbZeroTimestampKeys[i], 1);
        } else if (dlbInput.previous[i] > 0) {
            flow.set(dlbZeroTimestampKeys[i], currentTime);
        }
    }

    data1.properties.inputLimit = Power_A
    data2.properties.inputLimit = Power_B
    data3.properties.inputLimit = Power_C

    //saving power posted and posted to all devices, for including in GET status message
    latestPowerCmd = inputLimit
    latestPowerCmd_1 = Power_A
    latestPowerCmd_2 = Power_B
    latestPowerCmd_3 = Power_C
    inputLimit_effective = Power_A + Power_B + Power_C;

    flow.set('latestPowerCmd', latestPowerCmd)
    flow.set('latestPowerCmd_1', latestPowerCmd_1)
    flow.set('latestPowerCmd_2', latestPowerCmd_2)
    flow.set('latestPowerCmd_3', latestPowerCmd_3)
    flow.set('inputLimit', inputLimit)
    flow.set('inputLimit_effective', inputLimit_effective)

}



//################

// Discharging - outputlimit; instead of available storage, use available charge stored

if ("outputLimit" in data.properties && skip_outputLimit === 0) {
