    if (dualmode_damper_enable === 1 && outputLimit > singleMode_upperlimit_out && outputLimit <= (singleMode_upperlimit_out + dualmode_damper_amount) && device_active_count_previous === 1 && latestPowerCmd_previous !== 0) {
