    const entityId = String(flow.get('dlb_p1_phase_' + phase + '_entity_id') || '').trim();
    if (!entityId || !entityId.includes('.')) continue;
    messages.push({
        payload: {
            protocol: 'http',
            method: 'get',
            path: '/api/states/' + entityId
        },
        phase: phase,
        topic: entityId,
        dlb_p1_source: 'ha_rest_last_reported_poll'
    });
}
if (!messages.length) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'waiting for P1 entity IDs' });
    return null;
}
node.status({ fill: 'green', shape: 'dot', text: 'checking ' + messages.length + ' current entities' });
return [messages];

// The three HA Events: state nodes explicitly set msg.phase and msg.topic.
// DLB v2.3 stores those entity IDs and reuses them for read-only targeted
// Home Assistant state reads. The poll does not control Zendures; it only reads the configured entity
// state objects from Home Assistant and validates freshness with last_reported.
function parseAmp(value) {
    if (value === undefined || value === null) return NaN;
    const parsed = parseFloat(String(value).replace(',', '.'));
    return Number.isFinite(parsed) ? parsed : NaN;
}

function parseTimestampSeconds(value) {
    if (value === undefined || value === null || value === '') return 0;
    if (typeof value === 'number' && Number.isFinite(value)) {
        return value > 100000000000 ? Math.floor(value / 1000) : Math.floor(value);
    }
    const ms = Date.parse(String(value));
    return Number.isFinite(ms) ? Math.floor(ms / 1000) : 0;
}

function getLastReportedSeconds(data) {
    const candidates = [
        data && data.last_reported,
        data && data.new_state && data.new_state.last_reported,
        data && data.event && data.event.new_state && data.event.new_state.last_reported,
        data && data.event && data.event.data && data.event.data.new_state && data.event.data.new_state.last_reported,
        data && data.event && data.event.data && data.event.data.last_reported
    ];
    for (const candidate of candidates) {
        const ts = parseTimestampSeconds(candidate);
        if (ts > 0) return ts;
    }
    return 0;
}

function formatTimeWithSeconds() {
    const d = new Date();
    const pad = n => String(n).padStart(2, '0');
    return pad(d.getHours()) + ':' + pad(d.getMinutes()) + ':' + pad(d.getSeconds());
}

function formatAmp(value) {
    const n = Number(value);
    return Number.isFinite(n) ? n.toFixed(2) + 'A' : 'n/a';
}

function updateCurrentStatus() {
    const now = Math.floor(Date.now() / 1000);
    const ages = [1, 2, 3].map(phase => {
        const ts = Number(flow.get('dlb_p1_phase_' + phase + '_last_update') || 0);
        return ts > 0 ? Math.max(0, now - ts) : null;
    });
    const maxAge = Number(flow.get('dynamic_load_balancing_p1_max_age_sec') || 15);
    const fresh = ages.every(age => age !== null && age <= maxAge);
    node.status({
        fill: fresh ? 'green' : 'yellow',
        shape: fresh ? 'dot' : 'ring',
        text: formatTimeWithSeconds()
            + ' | L1 ' + formatAmp(flow.get('p1_phase_1_current'))
            + ' | L2 ' + formatAmp(flow.get('p1_phase_2_current'))
            + ' | L3 ' + formatAmp(flow.get('p1_phase_3_current'))
            + ' | ' + (fresh ? 'reported' : 'stale')
    });
}

const phase = Number(msg.phase || 0);
const now = Math.floor(Date.now() / 1000);
const source = String(msg.dlb_p1_source || 'events_state');
const isReportPoll = source === 'ha_rest_last_reported_poll';
const stateObject = (msg.payload && typeof msg.payload === 'object') ? msg.payload : null;
const ampSource = stateObject && Object.prototype.hasOwnProperty.call(stateObject, 'state') ? stateObject.state : msg.payload;
const amp = parseAmp(ampSource);
const lastReported = getLastReportedSeconds(stateObject || msg.data);

if (![1, 2, 3].includes(phase) || !Number.isFinite(amp)) {
    flow.set('dlb_p1_status', 'error');
    flow.set('dlb_p1_error', 'Invalid P1 current update. Source=' + source + ', phase=' + phase + ', payload=' + JSON.stringify(msg.payload));
    node.status({ fill: 'red', shape: 'ring', text: formatTimeWithSeconds() + ' | invalid P1 current update' });

    const lastWarn = Number(flow.get('dlb_p1_last_error_warn_timestamp') || 0);
    const cooldown = Number(flow.get('dynamic_load_balancing_warn_cooldown_sec') || 10);
    if (now - lastWarn >= cooldown) {
        flow.set('dlb_p1_last_error_warn_timestamp', now);
        node.warn('[DLB] Invalid P1 current update. Check the configured Home Assistant phase-current entities.');
    }
    return null;
