function dlbAllocateByPhase(options) {
    const deviceCount = Math.min(3, Math.max(1, Number(options.deviceCount) || 0));
    const active = Array.from({ length: deviceCount }, (_, i) => i);
    const wanted = [0, 1, 2].map(i => Math.max(0, Number(options.wanted && options.wanted[i]) || 0));
    const eligible = [0, 1, 2].map(i => i < deviceCount && Boolean(options.eligible && options.eligible[i]));
