    });
    const deviceMax = [0, 1, 2].map(i => i < deviceCount ? Math.max(0, Number(options.deviceMax && options.deviceMax[i]) || 0) : 0);
    const phaseOf = [0, 1, 2].map(i => {
        const p = Number(options.phaseOf && options.phaseOf[i]);
        return Number.isInteger(p) && p >= 0 && p <= 2 ? p : i;
    });
    const phaseBudget = [0, 1, 2].map(p => Math.max(0, Number(options.phaseBudget && options.phaseBudget[p]) || 0));
    const requested = Math.max(0, Number(options.requested) || 0);
    const redistribute = Boolean(options.redistribute);

    // Start with Gast777's preferred SoC allocation, limited by the device max.
    let target = [0, 1, 2].map(i => eligible[i] ? Math.min(wanted[i], deviceMax[i]) : 0);

    // Each physical phase has one shared budget. If several Zendures are on a
    // restricted phase, preserve their original SoC-selected ratio.
    for (let p = 0; p < 3; p++) {
        const group = active.filter(i => eligible[i] && phaseOf[i] === p);
        const total = group.reduce((sum, i) => sum + target[i], 0);
        if (total > phaseBudget[p] + 0.0001) {
            const ratio = phaseBudget[p] / total;
            group.forEach(i => { target[i] *= ratio; });
        }
    }

    // Redistribute only through spare budget on a physical phase. Devices on a
    // shared restricted phase cannot double-count that phase's available watts.
    let remaining = Math.max(0, requested - target.reduce((sum, v) => sum + v, 0));
    let redistributed = 0;
    if (redistribute && remaining > 0.5) {
        for (let guard = 0; guard < 20 && remaining > 0.5; guard++) {
            const phaseUsed = [0, 1, 2].map(p => active.filter(i => phaseOf[i] === p).reduce((sum, i) => sum + target[i], 0));
            const candidates = active.filter(i => {
                const p = phaseOf[i];
                return eligible[i] && deviceMax[i] - target[i] > 0.5 && phaseBudget[p] - phaseUsed[p] > 0.5;
            });
            if (!candidates.length) break;
            let totalWeight = candidates.reduce((sum, i) => sum + weights[i], 0);
            if (totalWeight <= 0) totalWeight = candidates.length;
            const before = remaining;
            let added = 0;
            candidates.forEach(i => {
                const p = phaseOf[i];
                const share = before * ((weights[i] > 0 ? weights[i] : 1) / totalWeight);
                const phaseRoom = Math.max(0, phaseBudget[p] - phaseUsed[p]);
                const deviceRoom = Math.max(0, deviceMax[i] - target[i]);
                const add = Math.min(share, phaseRoom, deviceRoom);
                if (add > 0) {
                    target[i] += add;
                    phaseUsed[p] += add;
                    added += add;
                }
            });
            remaining -= added;
            redistributed += added;
            if (added <= 0.1) break;
        }
    }

    // Integer commands; correct any rounding that might exceed a shared phase budget.
    target = target.map((v, i) => Math.max(0, Math.min(deviceMax[i], Math.floor(v))));
    for (let p = 0; p < 3; p++) {
        const group = active.filter(i => phaseOf[i] === p);
        let excess = group.reduce((sum, i) => sum + target[i], 0) - Math.floor(phaseBudget[p]);
        while (excess > 0 && group.some(i => target[i] > 0)) {
            const largest = group.slice().sort((a, b) => target[b] - target[a])[0];
            const reduce = Math.min(excess, target[largest]);
            target[largest] -= reduce;
            excess -= reduce;
        }
    }
    const phaseUsed = [0, 1, 2].map(p => active.filter(i => phaseOf[i] === p).reduce((sum, i) => sum + target[i], 0));
    const total = target.reduce((sum, v) => sum + v, 0);
    return { target, phaseUsed, phaseBudget, remaining: Math.max(0, requested - total), redistributed: Math.max(0, redistributed) };
}

function calculateDlbPhaseBudget(groupPrevious, currentA, voltage, softA, maxA, softRampDownStepW) {
    const current = Number(currentA);
    const volts = Number(voltage);
    const group = Math.max(0, Number(groupPrevious) || 0);
    const softLimit = Math.max(0, Number(softA) || 0);
    const hardLimit = Math.max(softLimit, Number(maxA) || softLimit);
    const stepW = Math.max(0, Number(softRampDownStepW) || 0);

    if (!Number.isFinite(current) || !Number.isFinite(volts) || volts <= 0) {
        return { budget: 0, mode: 'invalid', softLimitedW: 0 };
    }

    // Hard/emergency zone: at or above the configured max current, correct
    // immediately toward the hard limit. This bypasses soft step limiting.
    if (current >= hardLimit) {
        const budget = Math.max(0, Math.floor(group + ((hardLimit - current) * volts)));
        return { budget, mode: 'hard', softLimitedW: 0 };
    }

    const softBudget = Math.max(0, Math.floor(group + ((softLimit - current) * volts)));

    // Soft zone: above the soft limit but below the hard limit. Do not cut all
    // the way down unless the over-current is large enough or step limiting is disabled.
    if (current > softLimit) {
        if (stepW <= 0) {
            return { budget: softBudget, mode: 'soft', softLimitedW: 0 };
        }
        const steppedBudget = Math.max(0, Math.floor(group - stepW));
        const budget = Math.max(softBudget, steppedBudget);
        return { budget, mode: budget > softBudget + 0.5 ? 'soft_step' : 'soft', softLimitedW: Math.max(0, budget - softBudget) };
    }

    return { budget: softBudget, mode: 'normal', softLimitedW: 0 };
}

function applyDlbRampUpLimit(result, context) {
