    const wanted = [0, 1, 2].map(i => Math.max(0, Number(context.wanted && context.wanted[i]) || 0));
    const previous = [0, 1, 2].map(i => Math.max(0, Number(context.previous && context.previous[i]) || 0));
    const eligible = [0, 1, 2].map(i => i < deviceCount && Boolean(context.eligible && context.eligible[i]));
    const deviceMax = [0, 1, 2].map(i => i < deviceCount ? Math.max(0, Number(context.deviceMax && context.deviceMax[i]) || wanted[i] || 0) : 0);
    const phaseOf = [0, 1, 2].map(i => {
        const p = Number(context.phaseOf && context.phaseOf[i]);
        return Number.isInteger(p) && p >= 0 && p <= 2 ? p : i;
    });
    const phaseBudget = [0, 1, 2].map(p => Math.max(0, Number(result.phaseBudget && result.phaseBudget[p]) || 0));
    const requested = Math.max(0, Number(context.requested) || 0);
    let target = [0, 1, 2].map(i => Math.max(0, Number(result.target && result.target[i]) || 0));

    // No ramp configuration means v2.3-style immediate recovery.
    if (waitSec <= 0 && stepW <= 0) {
        return Object.assign({}, result, { rampActive: 0, rampDelayed: 0, rampLimitedW: 0 });
    }

    let finalTarget = target.slice();
    let rampActive = 0;
    let rampDelayed = 0;
    let rampLimitedW = 0;

    for (let p = 0; p < 3; p++) {
        const group = active.filter(i => phaseOf[i] === p && eligible[i]);
        if (!group.length) {
            flow.set('dlb_ramp_phase_' + (p + 1) + '_active', 0);
            flow.set('dlb_ramp_phase_' + (p + 1) + '_space_since', 0);
            continue;
        }

        const cappedWantedGroup = group.reduce((sum, i) => sum + Math.min(wanted[i], deviceMax[i]), 0);
        const targetGroup = group.reduce((sum, i) => sum + target[i], 0);
        const previousGroup = group.reduce((sum, i) => sum + previous[i], 0);
