        const rampPrefix = 'dlb_ramp_phase_' + (p + 1);
        const keyActive = rampPrefix + '_active';
        const keySpaceSince = rampPrefix + '_space_since';
        const keyLastStep = rampPrefix + '_last_step';

        let rampArmed = Number(flow.get(keyActive) || 0) === 1;
        if (phaseProtectionNow || targetGroup < previousGroup - 0.5) {
            flow.set(keyActive, 1);
            rampArmed = true;
        }

        // Phase protection must always throttle down immediately. Waiting and
        // step limiting only apply when power is allowed to rise again.
        if (targetGroup < previousGroup - 0.5) {
            flow.set(keySpaceSince, 0);
            continue;
        }

        if (!rampArmed) continue;

        // No consecutive headroom yet. Reset the space timer until the phase
        // budget allows the group command to increase again.
        if (targetGroup <= previousGroup + 0.5) {
            flow.set(keySpaceSince, 0);
            if (!phaseProtectionNow && cappedWantedGroup <= 0.5) {
                flow.set(keyActive, 0);
                flow.set(keyLastStep, 0);
            }
            continue;
        }

        let spaceSince = Number(flow.get(keySpaceSince) || 0);
        if (spaceSince <= 0) {
            spaceSince = now;
            flow.set(keySpaceSince, spaceSince);
        }

        let allowedGroup = targetGroup;
        if (now - spaceSince < waitSec) {
            allowedGroup = previousGroup;
            rampDelayed = 1;
        } else if (stepW > 0) {
            const lastStep = Number(flow.get(keyLastStep) || 0);
            const stepDue = intervalSec <= 0 || lastStep <= 0 || now - lastStep >= intervalSec;
            if (!stepDue) {
                allowedGroup = previousGroup;
                rampDelayed = 1;
            } else {
                allowedGroup = Math.min(targetGroup, previousGroup + stepW);
                if (allowedGroup > previousGroup + 0.5) {
                    flow.set(keyLastStep, now);
                }
            }
        }

        if (allowedGroup < targetGroup - 0.5) {
            rampActive = 1;
            rampLimitedW += targetGroup - allowedGroup;

            const baseValues = group.map(i => Math.min(target[i], previous[i]));
            const baseSum = baseValues.reduce((sum, v) => sum + v, 0);
            const growPotential = group.reduce((sum, i, idx) => sum + Math.max(0, target[i] - baseValues[idx]), 0);
