            flow.set(keySpaceSince, 0);
            flow.set(keyLastStep, 0);
        }
    }

    const phaseUsed = [0, 1, 2].map(p => active.filter(i => phaseOf[i] === p).reduce((sum, i) => sum + finalTarget[i], 0));
    const total = finalTarget.reduce((sum, v) => sum + v, 0);
    const output = Object.assign({}, result);
    output.target = finalTarget;
    output.phaseUsed = phaseUsed;
    output.remaining = Math.max(0, requested - total);
    output.rampActive = rampActive;
    output.rampDelayed = rampDelayed;
    output.rampLimitedW = Math.floor(rampLimitedW);
    return output;
}

